import sys


def main():
    data = sys.stdin.buffer.read()
    flat = data.replace(b"\n", b",").split(b",")
    # flat[0:3] is header; then id,cat,val repeated; trailing empties dropped
    n = (len(flat) - 3) // 3
    cats = flat[4:3 + 3 * n:3]
    vals = flat[5:3 + 3 * n:3]
    sums = {}
    get = sums.get
    for cat, v in zip(cats, vals):
        if not cat:
            continue
        sums[cat] = get(cat, 0.0) + float(v)
    out = []
    for cat in sorted(sums):
        out.append(cat.decode() + "," + ("%.2f" % sums[cat]))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


if __name__ == "__main__":
    main()
